const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Point([121.5, 31.2]);
  const wuhan = ee.Geometry.Point([114.3, 30.6]);
  const startDate = '2020-04-20';
  const endDate = '2020-05-12';

  // 2. Data Acquisition - TROPOMI NO2 data
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .select('tropospheric_NO2_column_number_density');

  // Check if collection is empty
  const collectionSize = no2Collection.size().getInfo();
  console.log(`Total NO2 images in period: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No NO2 data available for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean NO2 for Shanghai
  const shanghaiMean = no2Collection.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  // Calculate mean NO2 for Wuhan
  const wuhanMean = no2Collection.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  // Get pixel counts to validate data
  const shanghaiCount = no2Collection.mean().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  const wuhanCount = no2Collection.mean().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density');

  const shanghaiVal = shanghaiMean.getInfo();
  const wuhanVal = wuhanMean.getInfo();
  const shanghaiPixels = shanghaiCount.getInfo();
  const wuhanPixels = wuhanCount.getInfo();

  console.log(`Shanghai NO2: ${shanghaiVal ? shanghaiVal.toFixed(6) : 'null'}, Pixels: ${shanghaiPixels}`);
  console.log(`Wuhan NO2: ${wuhanVal ? wuhanVal.toFixed(6) : 'null'}, Pixels: ${wuhanPixels}`);

  // 5. Validation & Final Answer
  if (shanghaiVal === null || wuhanVal === null || 
      isNaN(shanghaiVal) || isNaN(wuhanVal) ||
      shanghaiPixels === 0 || wuhanPixels === 0) {
    if (shanghaiPixels === 0 || wuhanPixels === 0) {
      console.log("No valid pixels in one or both locations.");
      console.log("<answer>C2</answer>");
    } else {
      console.log("Calculation resulted in invalid values.");
      console.log("<answer>C3</answer>");
    }
  } else if (shanghaiVal > wuhanVal) {
    console.log("Shanghai NO2 higher than Wuhan.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Shanghai NO2 not higher than Wuhan.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
